refentry.refsect1:
&reftitle.parameters;




   ftp

     &ftp.parameter.ftp;



   filename



     Il file da cui estrarre l'orario dell'ultima modifica.

&reftitle.returnvalues;


 Restituisce l'orario dell'ultima modifica come timestamp Unix locale in caso di successo, o -1 in caso di
 errore.

  &reftitle.examples;



    Esempio di ftp_mdtm


<?php

$file = 'somefile.txt';

// stabilisce la connessione
$ftp = ftp_connect($ftp_server);

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

//  ottiene l'orario dell'ultima modifica
$buff = ftp_mdtm($ftp, $file);

if ($buff != -1) {
    // somefile.txt è stato modificato l'ultima volta il: March 26 2003 14:16:41.
    echo "$file è stato modificato l'ultima volta il: " . date("F d Y H:i:s.", $buff);
} else {
    echo "Impossibile ottenere mdtime";
}

// chiude la connessione
ftp_close($ftp);

?>
